-- Encounter codes (PRD 11 §4.0). Generated by Prisma; edited by hand so existing encounters get
-- numbers before the columns become required: add nullable → backfill → counters → NOT NULL.

-- AlterTable
ALTER TABLE "Encounter" ADD COLUMN     "code" TEXT,
ADD COLUMN     "encounterNumber" INTEGER;

-- Backfill: number each organisation's encounters in arrival order (id breaks ties), and build the
-- code from the year they opened in Lagos time. arrivedAt is stored as UTC without a zone.
-- The number is padded to at least 5 digits and never cut (lpad alone would truncate longer ones).
WITH numbered AS (
    SELECT "id",
           ROW_NUMBER() OVER (PARTITION BY "organizationId" ORDER BY "arrivedAt", "id") AS n,
           to_char(("arrivedAt" AT TIME ZONE 'UTC') AT TIME ZONE 'Africa/Lagos', 'YY') AS yy
    FROM "Encounter"
)
UPDATE "Encounter" e
SET "encounterNumber" = numbered.n,
    "code"            = 'ENC-' || numbered.yy || '-' || lpad(numbered.n::text, GREATEST(5, length(numbered.n::text)), '0')
FROM numbered
WHERE e."id" = numbered."id";

-- Each organisation's counter continues from its highest number, so new check-ins never reuse one
INSERT INTO "SequenceCounter" ("scope", "lastNumber")
SELECT 'encounter:' || "organizationId", MAX("encounterNumber")
FROM "Encounter"
GROUP BY "organizationId"
ON CONFLICT ("scope") DO UPDATE SET "lastNumber" = GREATEST("SequenceCounter"."lastNumber", EXCLUDED."lastNumber");

-- Every encounter now has both; from here they're required
ALTER TABLE "Encounter" ALTER COLUMN "code" SET NOT NULL,
ALTER COLUMN "encounterNumber" SET NOT NULL;

-- CreateIndex
CREATE UNIQUE INDEX "Encounter_organizationId_encounterNumber_key" ON "Encounter"("organizationId", "encounterNumber");

-- CreateIndex
CREATE UNIQUE INDEX "Encounter_organizationId_code_key" ON "Encounter"("organizationId", "code");
